# Deadly Riposte (FDN): "Deadly Riposte deals 3 damage to target tapped creature and you gain 2
# life."
# Damage: Turn to Slag's atom at 3, the target M21 Swift Response's "target tapped creature"
# (IS_TAPPED + TYPE_EQ Creature); then the life gain (B5c-bullet-gain-life atom, 2), a Seq in
# printed order.
abilities = [
    SpellAbility(
        kind=SpellKind.INSTANT,
        effect=Seq(
            steps=(
                A(Verb.DEAL_DAMAGE, {
                    'amount': QConst(value=3),
                    'target': Selector(
                        count=QConst(value=1),
                        mode=SelectorMode.TARGET,
                        filter=FAnd(
                            children=(
                                FAtom(pred=FAtomPred.IS_TAPPED),
                                FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                            ),
                        ),
                        zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
                    ),
                }),
                A(Verb.GAIN_LIFE, {'amount': QConst(value=2), 'controller': ControllerRef.YOU}),
            ),
        ),
    ),
]
